export const HERO_ASSET_BY_ID = readonlyLookup(HERO_ASSET_MANIFEST.heroes.map(hero => [hero.heroId, hero]));
export const ACTION_ASSET_BY_ID = readonlyLookup(HERO_ASSET_MANIFEST.heroes.flatMap(hero => Object.values(hero.abilities).map(action => [action.id, action])));
export const WEAPON_ASSET_BY_ID = readonlyLookup(HERO_ASSET_MANIFEST.heroes.map(hero => [hero.weapon.id, hero.weapon]));

export const getHeroAsset = heroId => HERO_ASSET_BY_ID.get(String(heroId || '')) || null;
export const getActionAsset = actionId => ACTION_ASSET_BY_ID.get(String(actionId || '')) || null;
export const getWeaponAsset = weaponId => WEAPON_ASSET_BY_ID.get(String(weaponId || '')) || null;
